  border: 1px solid #cbd5e1;
  border-radius: 6px;
  padding: 12px;
  margin-bottom: 12px;
}

.bkt-vendor-submit-btn {
  background: #2563eb;
  border: none;
  border-radius: 6px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  height: 36px;
  padding: 0 16px;
