}

.bkt-footer {
  border-top: 1px solid #e2e8f0;
  background: #ffffff;
  padding: 16px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 24px;
  border-radius: 8px;
}

.bkt-status-pane {
  flex: 1;
