  font-weight: 700;
  padding: 10px 20px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.bkt-proceed-btn.active {
  background: #2563eb;
  box-shadow: 0 2px 4px rgba(37, 99, 235, 0.15);
}

.bkt-proceed-btn.active:hover {
