.bkt-vendor-pill {
	position: relative;
}

.vendor-tooltip {
	position: absolute;
	bottom: 110%;
	left: 0;
	width: 280px;
	background: #0f172a;
	border: 1px solid #1e293b;
	border-radius: 8px;
	padding: 12px;
	box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
	z-index: 1000;
	opacity: 0;
	visibility: hidden;
	transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
	transform-origin: bottom center;
	pointer-events: none;
	text-align: left;
}

.bkt-vendor-pill:hover .vendor-tooltip {
	opacity: 1;
	visibility: visible;
	transform: translateY(-4px);
}

.vendor-tooltip::after {
	content: '';
	position: absolute;
	top: 100%;
	left: 30px;
	margin-left: -6px;
	border-width: 6px;
	border-style: solid;
	border-color: #0f172a transparent transparent transparent;
}

.vt-header {
	display: flex;
	justify-content: space-between;
	align-items: center;
	border-bottom: 1px solid #334155;
	padding-bottom: 8px;
	margin-bottom: 8px;
}

.vt-ai-label {
	font-size: 10px;
