	color: #fbbf24;
	letter-spacing: 0.05em;
	display: flex;
	align-items: center;
	gap: 4px;
}

.vt-score-pill {
	background: #064e3b;
	color: #34d399;
	border: 1px solid #047857;
	font-size: 10px;
	font-weight: 800;
	padding: 2px 6px;
