}

.vt-vendor-name {
	font-size: 13px;
	font-weight: 700;
	color: #ffffff;
	margin-bottom: 4px;
}

.vt-justification {
	font-size: 12px;
	color: #cbd5e1;
	line-height: 1.4;
}

