.vr-footer-status {
	font-size: 14px;
	font-weight: 600;
	display: flex;
	align-items: center;
	gap: 8px;
	padding: 8px 16px;
	border-radius: 6px;
	background: #f8fafc;
}

.vr-footer-status.success {
	color: #059669;
	background: #ecfdf5;
	border: 1px solid #a7f3d0;
}

.vr-footer-status.error {
	color: #dc2626;
	background: #fef2f2;
	border: 1px solid #fecaca;
}

.vr-footer-status.processing {
	color: #0284c7;
	background: #f0f9ff;
	border: 1px solid #bae6fd;
}

.vr-footer-status.locked {
	color: #475569;
	background: #f1f5f9;
	border: 1px solid #e2e8f0;
}

.vr-icon-spin {
	display: inline-block;
	animation: spin 2s linear infinite;
}

@keyframes spin {
	100% {
		transform: rotate(360deg);
	}
}

/* Modal Overlay (Ping-Pong Session) */
.vr-modal-overlay {
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	background: rgba(15, 23, 42, 0.6);
	backdrop-filter: blur(4px);
	z-index: 1000;
	display: flex;
	align-items: center;
	justify-content: center;
}

.vr-modal-box {
	background: #ffffff;
	border-radius: 12px;
	padding: 32px;
	width: 400px;
	max-width: 90%;
	box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
	text-align: center;
	animation: modalPop 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes modalPop {
	0% {
		transform: scale(0.95);
		opacity: 0;
	}

	100% {
		transform: scale(1);
		opacity: 1;
	}
}

.vr-modal-icon {
	font-size: 48px;
	margin-bottom: 16px;
}

.vr-modal-icon.processing {
	color: #0ea5e9;
}

.vr-modal-icon.success {
	color: #10b981;
}

.vr-modal-icon.error {
	color: #ef4444;
}

.vr-modal-box h3 {
	margin: 0 0 8px 0;
	font-size: 20px;
	color: #0f172a;
}

.vr-modal-box p {
	margin: 0 0 24px 0;
	font-size: 14px;
	color: #64748b;
	line-height: 1.5;
}

.vr-modal-actions {
	display: flex;
	gap: 12px;
	justify-content: center;
}

.vr-modal-btn {
	padding: 10px 20px;
	border-radius: 6px;
	font-weight: 600;
	font-size: 14px;
	cursor: pointer;
	border: none;
	transition: all 0.2s;
}

.vr-modal-btn.primary {
	background: #0ea5e9;
	color: white;
}

.vr-modal-btn.primary:hover {
	background: #0284c7;
}

.vr-modal-btn.secondary {
	background: #f1f5f9;
	color: #475569;
}

.vr-modal-btn.secondary:hover {
	background: #e2e8f0;
}

